/*
 * Deterministic 30 FPS 1080p MediaCodec H.264 + 120 Hz IMU trace.jsonl replay engine.
 *
 * Decodes recorded <session>/clip.mp4 and synchronized <session>/trace.jsonl streams captured by
 * FieldDataLogger (or generated by closed-loop validation harnesses), injecting 120 Hz remapped
 * IMU rotation matrices into GroundPlaneRaycaster and full-resolution 1920x1080 Yuv420Frame planes
 * into ScannerViewModel's exact production PushBroomCropper -> RfDetrTwoGraphGpuDetector ->
 * TemporalTargetTracker -> LockOnPinpointController pipeline.
 *
 * Main types:
 * - ReplaySessionItem: immutable descriptor for discovered REPLAY entries in the LCARS SRC drawer.
 * - ReplayRunSummary: structured end-of-clip metrics logged as GNEISSFIND_REPLAY_SUMMARY for adb CI.
 * - ReplayCameraSource: background MediaExtractor + MediaCodec + 120 Hz IMU pacing coordinator.
 */
package com.gneissfind.app.camera

import android.content.Context
import android.graphics.Bitmap
import android.media.Image
import android.media.MediaCodec
import android.media.MediaCodecInfo
import android.media.MediaExtractor
import android.media.MediaFormat
import android.util.Log
import com.gneissfind.app.logging.FieldDataLogger
import com.gneissfind.app.logging.ReplayFrameRecord
import com.gneissfind.app.logging.ReplayTraceBundle
import com.gneissfind.app.logging.ReplayTraceHeader
import com.gneissfind.app.tracking.GroundPlaneRaycaster
import com.gneissfind.app.vision.Yuv420Frame
import java.io.File
import java.nio.ByteBuffer
import java.util.Locale
import java.util.concurrent.atomic.AtomicBoolean
import java.util.concurrent.locks.LockSupport
import kotlin.math.max
import kotlin.math.min

/**
 * Immutable descriptor for a discovered `<session>` directory shown inside the LCARS `SRC` drawer.
 *
 * @property code Short LCARS row prefix (`R-01`, `R-02`, ...).
 * @property sessionName Session directory name (typically `<YYYYMMDD_HHMMSS>`).
 * @property sessionDirPath Canonical path to the session folder containing `clip.mp4` and `trace.jsonl`.
 * @property durationSec Approximate clip duration in seconds displayed as `[<dur>S]`.
 */
data class ReplaySessionItem(
    val code: String,
    val sessionName: String,
    val sessionDirPath: String,
    val durationSec: Int
) {
    /** Formatted LCARS drawer title (`REPLAY: <session>`). */
    val drawerTitle: String
        get() = "REPLAY: ${sessionName.uppercase(Locale.US)}"

    /** Formatted LCARS drawer subtitle (`1080P30 MP4 + 120HZ IMU • [<dur>S]`). */
    val drawerSubtitle: String
        get() = String.format(Locale.US, "1080P30 MP4 + 120HZ IMU • [%02dS]", durationSec.coerceAtLeast(1))
}

/**
 * End-of-clip validation summary emitted as a single `GNEISSFIND_REPLAY_SUMMARY` JSON log line
 * when a single-pass (`loopReplay = false`) replay finishes.
 */
data class ReplayRunSummary(
    val sessionName: String,
    val frames: Int,
    val locks: Int,
    val handovers: Int,
    val lostLocks: Int,
    val distractorJumps: Int,
    val distractorsRejected: Int = 0,
    val exceptions: Int
) {
    /** Formats the structured Logcat line parsed by `adb logcat -d -s GneissFindReplay:I`. */
    fun toLogLine(): String {
        val safeSession = sessionName.replace("\"", "")
        return "GNEISSFIND_REPLAY_SUMMARY " +
            "{\"session\":\"$safeSession\"," +
            "\"frames\":$frames," +
            "\"locks\":$locks," +
            "\"handovers\":$handovers," +
            "\"lost_locks\":$lostLocks," +
            "\"distractor_jumps\":$distractorJumps," +
            "\"distractors_rejected\":$distractorsRejected," +
            "\"exceptions\":$exceptions}"
    }
}

/**
 * Zero-copy [Yuv420Frame] adapter over a decoded [MediaCodec] output [Image] (`YUV_420_888`).
 *
 * Frames encoded by [FieldDataLogger] are already oriented upright (`1920x1080`, `rotationDegrees = 0`).
 */
private class MediaImageYuv420Frame(
    image: Image,
    override val timestampNs: Long
) : Yuv420Frame {
    override val width: Int = image.width
    override val height: Int = image.height
    override val rotationDegrees: Int = 0

    private val planes = image.planes
    override val yBuffer: ByteBuffer = planes[0].buffer
    override val yRowStride: Int = planes[0].rowStride
    override val yPixelStride: Int = planes[0].pixelStride

    override val uBuffer: ByteBuffer = planes[1].buffer
    override val uRowStride: Int = planes[1].rowStride
    override val uPixelStride: Int = planes[1].pixelStride

    override val vBuffer: ByteBuffer = planes[2].buffer
    override val vRowStride: Int = planes[2].rowStride
    override val vPixelStride: Int = planes[2].pixelStride
}

/**
 * Fallback [Yuv420Frame] view over a contiguous semi-planar `NV12` [ByteBuffer] when a software
 * decoder returns `null` from `MediaCodec.getOutputImage`.
 */
private class Nv12BufferYuv420Frame(
    rawBuffer: ByteBuffer,
    override val width: Int,
    override val height: Int,
    rowStride: Int,
    sliceHeight: Int,
    override val timestampNs: Long
) : Yuv420Frame {
    override val rotationDegrees: Int = 0
    override val yRowStride: Int = max(width, rowStride)
    override val yPixelStride: Int = 1
    override val uRowStride: Int = max(width, rowStride)
    override val uPixelStride: Int = 2
    override val vRowStride: Int = max(width, rowStride)
    override val vPixelStride: Int = 2

    override val yBuffer: ByteBuffer
    override val uBuffer: ByteBuffer
    override val vBuffer: ByteBuffer

    init {
        val dup = rawBuffer.duplicate()
        val basePos = dup.position()
        val limit = dup.limit()
        val uvStart = min(limit, basePos + yRowStride * max(height, sliceHeight))

        val ySlice = rawBuffer.duplicate()
        ySlice.position(basePos)
        ySlice.limit(uvStart)
        yBuffer = ySlice.slice()

        val uSlice = rawBuffer.duplicate()
        uSlice.position(uvStart)
        uSlice.limit(limit)
        uBuffer = uSlice.slice()

        val vSlice = rawBuffer.duplicate()
        vSlice.position(min(limit, uvStart + 1))
        vSlice.limit(limit)
        vBuffer = vSlice.slice()
    }
}

/**
 * Decodes `<session>/clip.mp4` (`MediaExtractor` + `MediaCodec` in `COLOR_FormatYUV420Flexible`
 * buffer/image mode so CPU/GPU YUV planes remain accessible even with the OLED screen asleep)
 * alongside `<session>/trace.jsonl` (`120 Hz` IMU poses + per-frame Camera2 telemetry).
 */
class ReplayCameraSource(
    private val appContext: Context,
    private val raycaster: GroundPlaneRaycaster,
    private val onSessionHeaderLoaded: (ReplayTraceHeader) -> Unit,
    private val onReplayFrameAvailable: (
        yuvFrame: Yuv420Frame,
        telemetry: CameraExposureTelemetry,
        previewBitmap: Bitmap,
        frameSeq: Long,
         releaseCallback: () -> Unit
    ) -> Unit,
    private val onTryAutoLockAtFrame: (frameIndex: Int) -> Boolean,
    private val onBuildRunSummary: (sessionName: String, totalFrames: Int, caughtExceptions: Int) -> ReplayRunSummary,
    private val onSinglePassCompleted: (ReplayRunSummary) -> Unit = {}
) : AutoCloseable {

    private val running = AtomicBoolean(false)
    @Volatile
    private var workerThread: Thread? = null

    // Double-buffered 960x540 ARGB_8888 viewport bitmaps + scratch array (zero per-frame heap churn)
    private val previewBitmaps: Array<Bitmap> = arrayOf(
        Bitmap.createBitmap(PREVIEW_WIDTH_PX, PREVIEW_HEIGHT_PX, Bitmap.Config.ARGB_8888),
        Bitmap.createBitmap(PREVIEW_WIDTH_PX, PREVIEW_HEIGHT_PX, Bitmap.Config.ARGB_8888)
    )
    private val previewArgbScratch = IntArray(PREVIEW_WIDTH_PX * PREVIEW_HEIGHT_PX)
    private var previewToggleIdx = 0
    private var emittedFrameSeq = 0L

    /** Currently active session folder name, or `null` when stopped. */
    @Volatile
    var activeSessionName: String? = null
        private set

    /** Whether replay playback is currently running. */
    val isRunning: Boolean
        get() = running.get()

    /**
     * Starts decoding [sessionDir] on a dedicated `GneissFind-Replay` thread, stopping any previous
     * replay session cleanly first.
     */
    @Synchronized
    fun startSession(
        sessionDir: File,
        loopReplay: Boolean = true,
        autoLockFrameIdx: Int = -1
    ): Boolean {
        stopSession()
        val clipFile = File(sessionDir, FieldDataLogger.CLIP_FILE_NAME)
        val traceFile = File(sessionDir, FieldDataLogger.TRACE_FILE_NAME)
        if (!clipFile.isFile || !traceFile.isFile) {
            Log.e(TAG, "Missing clip.mp4 or trace.jsonl in ${sessionDir.absolutePath}")
            return false
        }

        val traceBundle = try {
            FieldDataLogger.parseReplayTraceFile(traceFile)
        } catch (t: Throwable) {
            Log.e(TAG, "Failed parsing trace.jsonl in ${sessionDir.absolutePath}", t)
            return false
        }

        running.set(true)
        activeSessionName = sessionDir.name
        raycaster.isReplayModeActive = true

        val thread = Thread(
            {
                runPlaybackLoop(
                    sessionDir = sessionDir,
                    clipFile = clipFile,
                    traceBundle = traceBundle,
                    loopReplay = loopReplay,
                    autoLockFrameIdx = autoLockFrameIdx
                )
            },
            "GneissFind-Replay"
        ).apply {
            priority = Thread.NORM_PRIORITY + 1
            isDaemon = true
        }
        workerThread = thread
        thread.start()
        return true
    }

    /** Stops any active replay thread and restores `raycaster.isReplayModeActive = false`. */
    @Synchronized
    fun stopSession() {
        running.set(false)
        val thread = workerThread
        workerThread = null
        if (thread != null && thread !== Thread.currentThread()) {
            thread.interrupt()
            runCatching { thread.join(1_200L) }
        }
        activeSessionName = null
        raycaster.isReplayModeActive = false
    }

    override fun close() {
        stopSession()
    }

    private fun runPlaybackLoop(
        sessionDir: File,
        clipFile: File,
        traceBundle: ReplayTraceBundle,
        loopReplay: Boolean,
        autoLockFrameIdx: Int
    ) {
        var extractor: MediaExtractor? = null
        var decoder: MediaCodec? = null
        var totalDecodedFrames = 0
        var caughtExceptions = 0
        var autoLockTriggered = false

        try {
            val header = traceBundle.header
            onSessionHeaderLoaded(header)

            val mediaExtractor = MediaExtractor()
            extractor = mediaExtractor
            mediaExtractor.setDataSource(clipFile.absolutePath)

            val videoTrackIdx = selectVideoTrack(mediaExtractor)
            if (videoTrackIdx < 0) {
                Log.e(TAG, "No video track found in ${clipFile.absolutePath}")
                caughtExceptions++
                return
            }
            mediaExtractor.selectTrack(videoTrackIdx)
            val trackFormat = mediaExtractor.getTrackFormat(videoTrackIdx)
            val mime = trackFormat.getString(MediaFormat.KEY_MIME) ?: MediaFormat.MIMETYPE_VIDEO_AVC
            trackFormat.setInteger(
                MediaFormat.KEY_COLOR_FORMAT,
                MediaCodecInfo.CodecCapabilities.COLOR_FormatYUV420Flexible
            )

            val codec = MediaCodec.createDecoderByType(mime)
            decoder = codec
            codec.configure(trackFormat, null, null, 0)
            codec.start()

            val bufferInfo = MediaCodec.BufferInfo()
            val imuRecords = traceBundle.imuRecords
            val frameRecords = traceBundle.frameRecords
            val nominalFrameIntervalNs = 1_000_000_000L / header.fps.coerceIn(1, 120)
            val baseTraceNs = computeBaseTraceTimestampNs(traceBundle)

            while (running.get()) {
                raycaster.isReplayModeActive = true
                raycaster.resetRingBuffer(header.refPitchDeg)

                val passStartMonoNs = System.nanoTime()
                var imuCursor = 0
                var passFrameIdx = 0
                var inputEos = false
                var outputEos = false

                while (running.get() && !outputEos) {
                    if (!inputEos) {
                        val inIdx = codec.dequeueInputBuffer(CODEC_POLL_TIMEOUT_US)
                        if (inIdx >= 0) {
                            val inBuf = codec.getInputBuffer(inIdx)
                            val sampleSize = if (inBuf != null) {
                                inBuf.clear()
                                mediaExtractor.readSampleData(inBuf, 0)
                            } else {
                                -1
                            }
                            if (sampleSize < 0) {
                                codec.queueInputBuffer(
                                    inIdx,
                                    0,
                                    0,
                                    0L,
                                    MediaCodec.BUFFER_FLAG_END_OF_STREAM
                                )
                                inputEos = true
                            } else {
                                val ptsUs = mediaExtractor.sampleTime.coerceAtLeast(0L)
                                codec.queueInputBuffer(inIdx, 0, sampleSize, ptsUs, 0)
                                mediaExtractor.advance()
                            }
                        }
                    }

                    val outIdx = codec.dequeueOutputBuffer(bufferInfo, CODEC_POLL_TIMEOUT_US)
                    when {
                        outIdx == MediaCodec.INFO_TRY_AGAIN_LATER -> Unit
                        outIdx == MediaCodec.INFO_OUTPUT_FORMAT_CHANGED -> Unit
                        outIdx >= 0 -> {
                            val isEos = (bufferInfo.flags and MediaCodec.BUFFER_FLAG_END_OF_STREAM) != 0
                            val hasPayload = bufferInfo.size > 0 &&
                                (bufferInfo.flags and MediaCodec.BUFFER_FLAG_CODEC_CONFIG) == 0

                            if (hasPayload && running.get()) {
                                val frameMeta = resolveFrameRecord(frameRecords, passFrameIdx)
                                val frameTraceNs = frameMeta?.timestampNs
                                    ?: (baseTraceNs + bufferInfo.presentationTimeUs.coerceAtLeast(0L) * 1_000L)
                                val targetFrameMonoNs = passStartMonoNs +
                                    (frameTraceNs - baseTraceNs).coerceAtLeast(passFrameIdx * nominalFrameIntervalNs)

                                // Inject all 120 Hz IMU samples up to this video frame's capture timestamp
                                while (imuCursor < imuRecords.size && running.get()) {
                                    val imu = imuRecords[imuCursor]
                                    if (imu.timestampNs > frameTraceNs) break
                                    val targetImuMonoNs = passStartMonoNs +
                                        (imu.timestampNs - baseTraceNs).coerceAtLeast(0L)
                                    sleepUntilMonotonicNs(targetImuMonoNs)
                                    if (!running.get()) break
                                    raycaster.injectReplayOrientationMatrix(
                                        timestampNs = max(System.nanoTime(), targetImuMonoNs),
                                        rotationMatrix9 = imu.rotationMatrix,
                                        rawPitchOverrideDeg = imu.pitchDeg
                                    )
                                    imuCursor++
                                }

                                sleepUntilMonotonicNs(targetFrameMonoNs)
                                val deliverMonoNs = max(System.nanoTime(), targetFrameMonoNs)

                                var bufferReleased = false
                                val outImg = runCatching { codec.getOutputImage(outIdx) }.getOrNull()
                                val releaseOnce = {
                                    if (!bufferReleased) {
                                        bufferReleased = true
                                        runCatching { outImg?.close() }
                                        runCatching { codec.releaseOutputBuffer(outIdx, false) }
                                    }
                                }

                                try {
                                    val yuvFrame: Yuv420Frame? = if (outImg != null) {
                                        MediaImageYuv420Frame(outImg, deliverMonoNs)
                                    } else {
                                        val outBuf = codec.getOutputBuffer(outIdx)
                                        if (outBuf != null) {
                                            outBuf.position(bufferInfo.offset)
                                            outBuf.limit(bufferInfo.offset + bufferInfo.size)
                                            val fmt = codec.outputFormat
                                            val w = fmt.getIntOrDefault(MediaFormat.KEY_WIDTH, header.width)
                                            val h = fmt.getIntOrDefault(MediaFormat.KEY_HEIGHT, header.height)
                                            val stride = fmt.getIntOrDefault(MediaFormat.KEY_STRIDE, w)
                                            val sliceH = fmt.getIntOrDefault(MediaFormat.KEY_SLICE_HEIGHT, h)
                                            Nv12BufferYuv420Frame(outBuf, w, h, stride, sliceH, deliverMonoNs)
                                        } else {
                                            null
                                        }
                                    }

                                    if (yuvFrame != null && running.get()) {
                                        val previewBmp = renderHalfResPreviewBitmap(yuvFrame)
                                        val zoom = frameMeta?.zoomRatio ?: header.zoomRatio
                                        val fyPx = if (kotlin.math.abs(zoom - header.zoomRatio) < 0.05f) {
                                            header.focalLengthPx
                                        } else {
                                            PushBroomCameraController.fallbackVerticalFocalLengthPx(zoom)
                                        }
                                        val telemetry = CameraExposureTelemetry(
                                            exposureTimeNs = frameMeta?.exposureNs
                                                ?: PushBroomCameraController.MAX_SHUTTER_EXPOSURE_NS,
                                            sensorIso = frameMeta?.iso ?: 400,
                                            activeZoomRatio = zoom,
                                            verticalFocalLengthPx = fyPx,
                                            streamWidth = yuvFrame.width,
                                            streamHeight = yuvFrame.height,
                                            measuredCameraFps = header.fps.toFloat()
                                        )
                                        val seq = ++emittedFrameSeq
                                        onReplayFrameAvailable(
                                            yuvFrame,
                                            telemetry,
                                            previewBmp,
                                            seq,
                                            releaseOnce
                                        )
                                        totalDecodedFrames++

                                        if (autoLockFrameIdx >= 0 &&
                                            !autoLockTriggered &&
                                            passFrameIdx >= autoLockFrameIdx
                                        ) {
                                            autoLockTriggered = onTryAutoLockAtFrame(passFrameIdx)
                                        }
                                        passFrameIdx++
                                    }
                                } catch (frameErr: Throwable) {
                                    caughtExceptions++
                                    Log.e(TAG, "Error processing replay frame $passFrameIdx", frameErr)
                                } finally {
                                    releaseOnce()
                                }
                            } else {
                                codec.releaseOutputBuffer(outIdx, false)
                            }

                            if (isEos) {
                                outputEos = true
                            }
                        }
                    }
                }

                if (!loopReplay || !running.get()) {
                    break
                }

                // Loop clip cleanly from frame 0
                mediaExtractor.seekTo(0L, MediaExtractor.SEEK_TO_CLOSEST_SYNC)
                codec.flush()
            }
        } catch (t: Throwable) {
            if (running.get()) {
                caughtExceptions++
                Log.e(TAG, "Replay loop aborted with exception", t)
            }
        } finally {
            runCatching { decoder?.stop() }
            runCatching { decoder?.release() }
            runCatching { extractor?.release() }

            if (!loopReplay) {
                // Allow in-flight GPU inference sweep on final frame to settle before emitting summary
                runCatching { Thread.sleep(220L) }
                val summary = onBuildRunSummary(sessionDir.name, totalDecodedFrames, caughtExceptions)
                Log.i(SUMMARY_LOG_TAG, summary.toLogLine())
                running.set(false)
                activeSessionName = null
                onSinglePassCompleted(summary)
            } else {
                running.set(false)
            }
        }
    }

    /**
     * Converts [frame] (`1920x1080` `Yuv420Frame`) at `2x` decimation into a pre-allocated
     * `960x540` `ARGB_8888` [Bitmap] in `< 1.0 ms` with zero heap allocations.
     */
    private fun renderHalfResPreviewBitmap(frame: Yuv420Frame): Bitmap {
        val srcW = frame.width.coerceAtLeast(2)
        val srcH = frame.height.coerceAtLeast(2)
        val dstW = PREVIEW_WIDTH_PX
        val dstH = PREVIEW_HEIGHT_PX

        val yBuf = frame.yBuffer.duplicate()
        val uBuf = frame.uBuffer.duplicate()
        val vBuf = frame.vBuffer.duplicate()
        val yLimit = yBuf.limit()
        val uLimit = uBuf.limit()
        val vLimit = vBuf.limit()
        if (yLimit <= 0 || uLimit <= 0 || vLimit <= 0) {
            return previewBitmaps[previewToggleIdx]
        }

        val yRowStride = frame.yRowStride
        val yPixStride = frame.yPixelStride
        val uRowStride = frame.uRowStride
        val uPixStride = frame.uPixelStride
        val vRowStride = frame.vRowStride
        val vPixStride = frame.vPixelStride

        val outPixels = previewArgbScratch
        var dstIdx = 0
        for (dy in 0 until dstH) {
            val sy = min(srcH - 1, (dy * srcH) / dstH)
            val yRowOffset = sy * yRowStride
            val uvRow = sy shr 1
            val uRowOffset = uvRow * uRowStride
            val vRowOffset = uvRow * vRowStride

            for (dx in 0 until dstW) {
                val sx = min(srcW - 1, (dx * srcW) / dstW)
                val uvCol = sx shr 1

                val yIdx = (yRowOffset + sx * yPixStride).coerceIn(0, yLimit - 1)
                val uIdx = PushBroomCropperSafeIdx.clampChromaIndex(
                    uRowOffset + uvCol * uPixStride,
                    uPixStride,
                    uLimit
                )
                val vIdx = PushBroomCropperSafeIdx.clampChromaIndex(
                    vRowOffset + uvCol * vPixStride,
                    vPixStride,
                    vLimit
                )

                val yVal = yBuf.get(yIdx).toInt() and 0xFF
                val uVal = (uBuf.get(uIdx).toInt() and 0xFF) - 128
                val vVal = (vBuf.get(vIdx).toInt() and 0xFF) - 128

                val r = (yVal + ((1436 * vVal) shr 10)).coerceIn(0, 255)
                val g = (yVal - ((352 * uVal + 731 * vVal) shr 10)).coerceIn(0, 255)
                val b = (yVal + ((1815 * uVal) shr 10)).coerceIn(0, 255)

                outPixels[dstIdx++] = (0xFF shl 24) or (r shl 16) or (g shl 8) or b
            }
        }

        val nextIdx = previewToggleIdx xor 1
        previewToggleIdx = nextIdx
        val bmp = previewBitmaps[nextIdx]
        bmp.setPixels(outPixels, 0, dstW, 0, 0, dstW, dstH)
        return bmp
    }

    private object PushBroomCropperSafeIdx {
        fun clampChromaIndex(rawIdx: Int, pixelStride: Int, limit: Int): Int {
            if (rawIdx in 0 until limit) return rawIdx
            if (rawIdx < 0) return 0
            val step = max(1, pixelStride)
            val excess = rawIdx - (limit - 1)
            val stepsBack = (excess + step - 1) / step
            return (rawIdx - stepsBack * step).coerceIn(0, limit - 1)
        }
    }

    companion object {
        private const val TAG = "ReplayCameraSource"
        const val SUMMARY_LOG_TAG = "GneissFindReplay"

        const val PREVIEW_WIDTH_PX = 960
        const val PREVIEW_HEIGHT_PX = 540
        private const val CODEC_POLL_TIMEOUT_US = 8_000L

        /**
         * Discovers all valid `<session>` folders across external media and internal fallback
         * directories and maps them to [ReplaySessionItem] descriptors (`R-01`, `R-02`, ...).
         */
        fun discoverReplaySessionItems(context: Context): List<ReplaySessionItem> {
            val dirs = FieldDataLogger.discoverValidReplaySessionDirs(context)
            return dirs.mapIndexed { idx, dir ->
                val dur = FieldDataLogger.readReplayDurationSecondsQuick(dir)
                ReplaySessionItem(
                    code = String.format(Locale.US, "R-%02d", idx + 1),
                    sessionName = dir.name,
                    sessionDirPath = dir.absolutePath,
                    durationSec = dur
                )
            }
        }

        /**
         * Resolves a `debug_replay_session` folder name or absolute path against
         * `Android/media/com.gneissfind.app/replays/` and `filesDir/replays/`.
         */
        fun resolveSessionDirectory(context: Context, nameOrPath: String): File? {
            val trimmed = nameOrPath.trim()
            if (trimmed.isEmpty()) return null
            val direct = File(trimmed)
            if (direct.isAbsolute && isValidReplayDir(direct)) {
                return direct
            }
            val extCandidate = File(FieldDataLogger.resolveBaseReplaysDir(context), trimmed)
            if (isValidReplayDir(extCandidate)) {
                return extCandidate
            }
            val intCandidate = File(FieldDataLogger.resolveFallbackInternalReplaysDir(context), trimmed)
            if (isValidReplayDir(intCandidate)) {
                return intCandidate
            }
            return FieldDataLogger.discoverValidReplaySessionDirs(context)
                .firstOrNull { it.name.equals(trimmed, ignoreCase = true) }
        }

        private fun isValidReplayDir(dir: File): Boolean {
            if (!dir.isDirectory) return false
            val clip = File(dir, FieldDataLogger.CLIP_FILE_NAME)
            val trace = File(dir, FieldDataLogger.TRACE_FILE_NAME)
            return clip.isFile && clip.length() > 256L && trace.isFile && trace.length() > 16L
        }

        private fun selectVideoTrack(extractor: MediaExtractor): Int {
            for (i in 0 until extractor.trackCount) {
                val fmt = extractor.getTrackFormat(i)
                val mime = fmt.getString(MediaFormat.KEY_MIME) ?: continue
                if (mime.startsWith("video/")) return i
            }
            return -1
        }

        private fun computeBaseTraceTimestampNs(bundle: ReplayTraceBundle): Long {
            val firstFrame = bundle.frameRecords.firstOrNull()?.timestampNs
            val firstImu = bundle.imuRecords.firstOrNull()?.timestampNs
            return when {
                firstFrame != null && firstImu != null -> min(firstFrame, firstImu)
                firstFrame != null -> firstFrame
                firstImu != null -> firstImu
                else -> 0L
            }
        }

        private fun resolveFrameRecord(
            frames: List<ReplayFrameRecord>,
            frameIdx: Int
        ): ReplayFrameRecord? {
            if (frames.isEmpty()) return null
            if (frameIdx in frames.indices && frames[frameIdx].frameIdx == frameIdx) {
                return frames[frameIdx]
            }
            return frames.firstOrNull { it.frameIdx == frameIdx }
                ?: frames.getOrNull(frameIdx.coerceIn(0, frames.lastIndex))
        }

        private fun MediaFormat.getIntOrDefault(key: String, defaultVal: Int): Int =
            if (containsKey(key)) runCatching { getInteger(key) }.getOrDefault(defaultVal) else defaultVal

        private fun sleepUntilMonotonicNs(targetMonoNs: Long) {
            while (true) {
                val remainingNs = targetMonoNs - System.nanoTime()
                if (remainingNs <= 150_000L) return
                val parkNs = min(remainingNs - 100_000L, 4_000_000L)
                LockSupport.parkNanos(parkNs)
                if (Thread.currentThread().isInterrupted) return
            }
        }
    }
}
